using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class WindDesignForm {
 WindBuildingModel buildingModel;readonly Timer buildingRefresh=new Timer{Interval=180};
 bool TryBuildingGeometry(out WindBuildingInput value){value=null;double w,l,e,a;if(!Inputs.ContainsKey("BuildingWidth")||!double.TryParse(Value("BuildingWidth"),NumberStyles.Float,CultureInfo.InvariantCulture,out w)||!double.TryParse(Value("BuildingLength"),NumberStyles.Float,CultureInfo.InvariantCulture,out l)||!double.TryParse(Value("Eave"),NumberStyles.Float,CultureInfo.InvariantCulture,out e)||!double.TryParse(Value("Apex"),NumberStyles.Float,CultureInfo.InvariantCulture,out a))return false;var b=new WindBuildingInput{Width=w,Length=l,Eave=e,Apex=a,RidgeDirection=((ComboBox)Inputs["RidgeDirection"]).SelectedIndex};try{b.Validate();value=b;return true;}catch{return false;}}
 // Exposure fetch uses the mean roof height h when building geometry is entered, otherwise the reference height z.
 double ExposureHeight(){WindBuildingInput b;if(TryBuildingGeometry(out b))return b.Height;double z;return Inputs.ContainsKey("Height")&&double.TryParse(Value("Height"),NumberStyles.Float,CultureInfo.InvariantCulture,out z)&&z>0?z:double.NaN;}
 void AddBuildingModel(FlowLayoutPanel panel){var page=Detach(panel);var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1};split.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,560));split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));split.RowStyles.Add(new RowStyle(SizeType.Percent,100));panel.Dock=DockStyle.Fill;buildingModel=new WindBuildingModel{Dock=DockStyle.Fill,Margin=new Padding(10)};split.Controls.Add(panel,0,0);split.Controls.Add(buildingModel,1,0);page.Controls.Add(split);foreach(string key in new[]{"BuildingWidth","BuildingLength","Eave","Apex","RidgeDirection"}){string captured=key;Inputs[key].Enter+=(s,e)=>{buildingModel.Highlight=captured;buildingModel.Invalidate();};Inputs[key].TextChanged+=(s,e)=>{buildingModel.Highlight=captured;RefreshBuildingModel();};}buildingRefresh.Tick+=(s,e)=>{buildingRefresh.Stop();UpdateResults();};FormClosed+=(s,e)=>buildingRefresh.Dispose();RefreshBuildingModel();}
 void RefreshBuildingModel(){if(buildingModel==null)return;WindBuildingInput b;buildingModel.Geometry=TryBuildingGeometry(out b)?b:null;buildingModel.Invalidate();if(!Restoring){buildingRefresh.Stop();buildingRefresh.Start();}}
}
class WindBuildingModel:Control {
 public WindBuildingInput Geometry;public string Highlight;
 /* the building pressures of the last Calculate (owner, 21 November 2026: "pag calculate sana nagpapakita din yung wind pressure sa
    building"): one principal wind axis at a time, right-click for the next one */
 public System.Collections.Generic.List<WindPressureRow> Pressures;public int Axis;
 void DrawPressures(Graphics g,WindBuildingInput b,WindModelPoint[] p,Func<WindModelPoint,PointF> project,int[][] faces){var axes=Pressures.Select(r=>r.Direction).Distinct().ToList();if(axes.Count==0)return;Axis=((Axis%axes.Count)+axes.Count)%axes.Count;var rows=Pressures.Where(r=>r.Direction==axes[Axis]).ToList();
  double ang=rows[0].Bearing*Math.PI/180;double sx=Math.Sin(ang),sy=Math.Cos(ang);Func<int[],WindModelPoint> centroid=f=>new WindModelPoint(f.Average(n=>p[n].X),f.Average(n=>p[n].Y),f.Average(n=>p[n].Z));
  var dots=faces.Select(f=>{var c=centroid(f);return c.X*sx+c.Y*sy;}).ToArray();int windward=Enumerable.Range(0,4).OrderByDescending(i=>dots[i]).First(),leeward=Enumerable.Range(0,4).OrderBy(i=>dots[i]).First();bool slopedRoof=rows.Any(r=>r.Surface=="Windward roof");
  Func<int,string> surface=i=>i==windward?"Windward wall":i==leeward?"Leeward wall":i<4?"Side walls":slopedRoof?(dots[i]>0?"Windward roof":"Leeward roof"):"Roof zone";
  Func<string,double[]> values=name=>{var list=rows.Where(r=>r.Surface.StartsWith(name)).ToList();if(list.Count==0)return null;var pos=list.Where(r=>r.GCpi>0).Select(r=>r.P).ToList();var neg=list.Where(r=>r.GCpi<0).Select(r=>r.P).ToList();return new[]{pos.Min(),pos.Max(),neg.Min(),neg.Max()};};
  double max=Math.Max(.01,rows.Max(r=>Math.Abs(r.P)));Func<double,string> f2=v=>(v>=0?"+":"")+v.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture);
  /* faces seen from the viewer, far ones first; every surface is listed under the model */
  double ct=Math.Cos(tilt),st=Math.Sin(tilt);double vx=Math.Sin(yaw)*ct,vy=Math.Cos(yaw)*ct,vz=st;
  Func<int,double[]> normal=i=>{var c=centroid(faces[i]);double hx=c.X,hy=c.Y,hl=Math.Max(1e-9,Math.Sqrt(hx*hx+hy*hy));return i<4?new[]{hx/hl,hy/hl,0}:new[]{hx/hl,hy/hl,Math.Abs(hx)+Math.Abs(hy)<1e-6?1:1.0};};
  var order=Enumerable.Range(0,faces.Length).Where(i=>{var n=normal(i);return n[0]*vx+n[1]*vy+n[2]*vz>1e-6;}).OrderBy(i=>{var c=centroid(faces[i]);return c.X*vx+c.Y*vy+c.Z*vz;}).ToList();
  var labels=new System.Collections.Generic.List<Tuple<PointF,string,Color>>();var listed=new System.Collections.Generic.List<Tuple<string,string,Color>>();
  for(int i=0;i<faces.Length;i++){string name=surface(i);var v=values(name);if(v==null)continue;double rep=Math.Abs(v[1])>=Math.Abs(v[2])?v[1]:v[2];Color c=rep>=0?Color.FromArgb(214,72,48):Color.FromArgb(46,110,190);
   string range=(Math.Abs(v[0]-v[1])>.005?f2(v[0])+" to "+f2(v[1]):f2(v[1]))+"  /  "+(Math.Abs(v[2]-v[3])>.005?f2(v[2])+" to "+f2(v[3]):f2(v[3]));if(!listed.Any(q=>q.Item1==name))listed.Add(Tuple.Create(name,range,c));
   if(!order.Contains(i))continue;}
  foreach(int i in order){string name=surface(i);var v=values(name);if(v==null)continue;double rep=Math.Abs(v[1])>=Math.Abs(v[2])?v[1]:v[2];Color c=rep>=0?Color.FromArgb(214,72,48):Color.FromArgb(46,110,190);int alpha=(int)(70+130*Math.Min(1,Math.Abs(rep)/max));
   var poly=faces[i].Select(n=>project(p[n])).ToArray();using(var white=new SolidBrush(ModernUi.Surface))g.FillPolygon(white,poly);using(var fill=new SolidBrush(Color.FromArgb(alpha,c)))g.FillPolygon(fill,poly);using(var pen=new Pen(Color.FromArgb(120,120,120),1.2f))g.DrawPolygon(pen,poly);
   /* pressure arrows normal to the face (owner, 21 November 2026: "yung pressure sa building as arrows"): into the face for + (toward
      the surface), out of it for - (suction), length to scale; on the windward wall they follow qz with height */
   {var c0=centroid(faces[i]);var e1=p[faces[i][1]];var e0=p[faces[i][0]];var e2=p[faces[i][2]];double ux=e1.X-e0.X,uy=e1.Y-e0.Y,uz=e1.Z-e0.Z,wx=e2.X-e1.X,wy=e2.Y-e1.Y,wz=e2.Z-e1.Z;double nx=uy*wz-uz*wy,ny=uz*wx-ux*wz,nz=ux*wy-uy*wx,nl=Math.Sqrt(nx*nx+ny*ny+nz*nz);if(nl>1e-9){nx/=nl;ny/=nl;nz/=nl;if(nx*c0.X+ny*c0.Y+nz*(i>=4?Math.Abs(c0.X)+Math.Abs(c0.Y)+1e-3:0)<0){nx=-nx;ny=-ny;nz=-nz;}
     bool posCase=Math.Abs(v[1])>=Math.Abs(v[2]);var caseRows=rows.Where(r=>r.Surface.StartsWith(name)&&(r.GCpi>0)==posCase).OrderBy(r=>r.Z).ToList();double maxLen=Math.Max(b.Width,b.Length)*.12;
     /* evenly spaced rows of parallel arrows, tails joined like a load diagram */
     Func<WindModelPoint,WindModelPoint,double,WindModelPoint> lerp=(qa,qb,t)=>new WindModelPoint(qa.X+(qb.X-qa.X)*t,qa.Y+(qb.Y-qa.Y)*t,qa.Z+(qb.Z-qa.Z)*t);var grid=new System.Collections.Generic.List<WindModelPoint[]>();double[] us={.12,.37,.63,.88};
     if(i<4){var wa=p[faces[i][0]];var wb=p[faces[i][1]];foreach(double h in new[]{.3,.75}){var row=us.Select(u=>{var q=lerp(wa,wb,u);return new WindModelPoint(q.X,q.Y,b.Eave*h);}).ToArray();grid.Add(row);}}
     else{var ea=p[i==4?4:5];var eb=p[i==4?7:6];var r0=p[8];var r1=p[9];foreach(double t in new[]{.3,.7}){var row=us.Select(u=>lerp(lerp(ea,eb,u),lerp(r0,r1,u),t)).ToArray();grid.Add(row);}}
     Color ac=rep>=0?Color.FromArgb(150,30,20):Color.FromArgb(18,62,140);
     using(var shaft=new Pen(ac,1.4f))using(var env=new Pen(Color.FromArgb(170,ac),1f){DashStyle=DashStyle.Dash})using(var head=new SolidBrush(ac))foreach(var row in grid){var tails=new System.Collections.Generic.List<PointF>();
      foreach(var q in row){double pv=rep;if(name=="Windward wall"&&caseRows.Count>1){pv=caseRows[0].P;foreach(var r in caseRows)if(r.Z<=q.Z+1e-9)pv=r.P;}double L=maxLen*Math.Max(.15,Math.Min(1,Math.Abs(pv)/max));
       var far=project(new WindModelPoint(q.X+nx*L,q.Y+ny*L,q.Z+nz*L));var on=project(q);PointF from=pv>=0?far:on,to=pv>=0?on:far;tails.Add(far);
       float dx=to.X-from.X,dy=to.Y-from.Y,dl=(float)Math.Sqrt(dx*dx+dy*dy);if(dl<3)continue;dx/=dl;dy/=dl;float hs=Math.Min(7f,dl*.45f);var tip=to;var bx=tip.X-dx*hs;var by=tip.Y-dy*hs;
       g.DrawLine(shaft,from.X,from.Y,bx,by);g.FillPolygon(head,new[]{tip,new PointF(bx-dy*hs*.42f,by+dx*hs*.42f),new PointF(bx+dy*hs*.42f,by-dx*hs*.42f)});}
      if(tails.Count>1)g.DrawLines(env,tails.ToArray());}}}
   labels.Add(Tuple.Create(project(centroid(faces[i])),name+"\n"+f2(Math.Abs(v[1])>=Math.Abs(v[0])?v[1]:v[0])+" / "+f2(Math.Abs(v[2])>=Math.Abs(v[3])?v[2]:v[3])+" kPa",c));}
  /* the wind arrow at the windward wall */
  double R=p.Max(q=>q.X*sx+q.Y*sy),len=Math.Max(3,Math.Max(b.Width,b.Length)*.4),zm=b.Eave*.5;var a0=project(new WindModelPoint(sx*(R+len),sy*(R+len),zm));var a1=project(new WindModelPoint(sx*(R+.3),sy*(R+.3),zm));
  using(var arrow=new Pen(Color.FromArgb(30,60,110),3.2f){CustomEndCap=new AdjustableArrowCap(5,6)})g.DrawLine(arrow,a0,a1);{string wt="WIND "+axes[Axis];var wsz=TextRenderer.MeasureText(wt,ModernUi.Strong);TextRenderer.DrawText(g,wt,ModernUi.Strong,new Point((int)a0.X-wsz.Width/2,(int)a0.Y-wsz.Height-4),Color.FromArgb(30,60,110));}
  foreach(var lb in labels){var sz=TextRenderer.MeasureText(lb.Item2,ModernUi.Body);var rect=new Rectangle((int)lb.Item1.X-sz.Width/2-4,(int)lb.Item1.Y-sz.Height/2-2,sz.Width+8,sz.Height+4);using(var bg=new SolidBrush(Color.FromArgb(235,255,255,255)))g.FillRectangle(bg,rect);using(var pen=new Pen(lb.Item3))g.DrawRectangle(pen,rect);TextRenderer.DrawText(g,lb.Item2,ModernUi.Body,rect,PowTheme.Ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
  /* all surfaces (also those at the back) */
  int ly=Height-84-listed.Count*20;TextRenderer.DrawText(g,"Surface pressures, wind "+axes[Axis]+"  (GCpi + / GCpi -, kPa)",ModernUi.Strong,new Point(18,ly-24),PowTheme.Ink);foreach(var it in listed){using(var sw=new SolidBrush(it.Item3))g.FillRectangle(sw,18,ly+5,12,10);TextRenderer.DrawText(g,it.Item1,ModernUi.Body,new Point(36,ly),PowTheme.Ink);TextRenderer.DrawText(g,it.Item2,ModernUi.Body,new Point(170,ly),PowTheme.Ink);ly+=20;}
  /* wind direction choice (owner, 21 November 2026: "may option if click saan galing yung wind magpapalit yung wind pressure") */
  chips.Clear();int cx=18;TextRenderer.DrawText(g,"Wind from:",ModernUi.Body,new Point(cx,104),PowTheme.Muted);cx+=TextRenderer.MeasureText("Wind from:",ModernUi.Body).Width+8;
  for(int k=0;k<axes.Count;k++){string t=axes[k];var sz=TextRenderer.MeasureText(t,ModernUi.Body);var rc=new Rectangle(cx,100,sz.Width+18,26);bool on=k==Axis;using(var bg=new SolidBrush(on?Color.FromArgb(27,48,76):Color.White))g.FillRectangle(bg,rc);using(var pen=new Pen(on?Color.FromArgb(27,48,76):PowTheme.Line))g.DrawRectangle(pen,rc);TextRenderer.DrawText(g,t,ModernUi.Body,rc,on?Color.White:PowTheme.Ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);chips.Add(rc);cx+=rc.Width+6;}
  TextRenderer.DrawText(g,"p = q G Cp - qi (GCpi); + toward the surface (red), - away (blue). Click a direction to show its pressures.",ModernUi.Body,new Rectangle(18,78,Width-36,22),PowTheme.Muted,TextFormatFlags.WordBreak);}
 readonly System.Collections.Generic.List<Rectangle> chips=new System.Collections.Generic.List<Rectangle>();
double yaw=-.65,tilt=.5,zoom=1;Point drag;bool rotating;
 struct V {public double X,Y,Z;public V(double x,double y,double z){X=x;Y=y;Z=z;}}
 public WindBuildingModel(){DoubleBuffered=true;ResizeRedraw=true;MinimumSize=new Size(300,320);MouseDown+=(s,e)=>{if(e.Button==MouseButtons.Right){if(Pressures!=null){Axis++;Invalidate();}return;}if(Pressures!=null){int hit=chips.FindIndex(r=>r.Contains(e.Location));if(hit>=0){Axis=hit;Invalidate();return;}}rotating=true;drag=e.Location;Capture=true;};MouseMove+=(s,e)=>{if(!rotating)return;yaw+=(e.X-drag.X)*.012;tilt=Math.Max(.2,Math.Min(1.15,tilt+(e.Y-drag.Y)*.007));drag=e.Location;Invalidate();};MouseUp+=(s,e)=>{rotating=false;Capture=false;};MouseWheel+=(s,e)=>{zoom=Math.Max(.5,Math.Min(2.5,zoom*(e.Delta>0?1.1:1/1.1)));Invalidate();};DoubleClick+=(s,e)=>{yaw=-.65;tilt=.5;zoom=1;Invalidate();};}
 protected override void OnPaint(PaintEventArgs e){/* drawings stay paper-white with dark ink in dark mode (owner, 21 November 2026: "pangit ng dark mode") */if(DesktopAppearance.Palette.Dark)e.Graphics.Clear(Color.White);using(new ReportPaperScope())PaintPaper(e);}
 void PaintPaper(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(ModernUi.Surface);g.SmoothingMode=SmoothingMode.AntiAlias;TextRenderer.DrawText(g,"Building geometry",PremiumControls.TitleFont,new Point(18,15),PowTheme.Ink);TextRenderer.DrawText(g,"Drag to rotate · scroll to zoom · double-click to reset",ModernUi.Body,new Rectangle(18,52,Width-36,42),PowTheme.Muted);var b=Geometry;if(b==null){TextRenderer.DrawText(g,"Enter valid width, length, eave and apex heights.",ModernUi.Body,new Rectangle(25,Height/2-30,Width-50,70),PowTheme.Muted,TextFormatFlags.WordBreak);return;}var p=WindBuildingGeometry.Vertices(b);Func<WindModelPoint,PointF> raw=v=>new PointF((float)(v.X*Math.Cos(yaw)-v.Y*Math.Sin(yaw)),(float)((v.X*Math.Sin(yaw)+v.Y*Math.Cos(yaw))*Math.Sin(tilt)-v.Z*Math.Cos(tilt)));var r=p.Select(raw).ToArray();double minx=r.Min(v=>v.X),maxx=r.Max(v=>v.X),miny=r.Min(v=>v.Y),maxy=r.Max(v=>v.Y),reserve=Pressures!=null&&Pressures.Count>0?Math.Min(Height*.35,30+6*20):0,scale=Math.Min((Width-100)/Math.Max(.1,maxx-minx),(Height-210-reserve)/Math.Max(.1,maxy-miny))*zoom;Func<WindModelPoint,PointF> project=v=>{var q=raw(v);return new PointF((float)(Width/2+(q.X-(minx+maxx)/2)*scale),(float)((Height-reserve)/2+25+(q.Y-(miny+maxy)/2)*scale));};var pts=p.Select(project).ToArray();int[][] faces={new[]{0,1,5,8,4},new[]{1,2,6,5},new[]{2,3,7,9,6},new[]{3,0,4,7},new[]{4,8,9,7},new[]{8,5,6,9}};for(int i=0;i<faces.Length;i++){using(var fill=new SolidBrush(i>=4?DesktopAppearance.Palette.Selected:ModernUi.Soft))g.FillPolygon(fill,faces[i].Select(n=>pts[n]).ToArray());using(var pen=new Pen(PowTheme.Line,1.2f))g.DrawPolygon(pen,faces[i].Select(n=>pts[n]).ToArray());}if(Pressures!=null&&Pressures.Count>0)try{DrawPressures(g,b,p,project,faces);}catch(Exception){}
  Dimension(g,pts[0],pts[1],"W = "+b.Width.ToString("0.##")+" m",Highlight=="BuildingWidth",0,24);Dimension(g,pts[1],pts[2],"L = "+b.Length.ToString("0.##")+" m",Highlight=="BuildingLength",25,15);Dimension(g,pts[1],pts[5],"Eave "+b.Eave.ToString("0.##")+" m",Highlight=="Eave",30,0);Dimension(g,project(WindBuildingGeometry.ApexDatum(b)),pts[8],"Apex "+b.Apex.ToString("0.##")+" m",Highlight=="Apex",-35,-14);
  TextRenderer.DrawText(g,"Mean roof h = "+b.Height.ToString("0.##")+" m  |  Roof slope = "+b.Angle.ToString("0.##")+"°",ModernUi.Strong,new Rectangle(18,Height-74,Width-36,30),PowTheme.Ink,TextFormatFlags.WordBreak);TextRenderer.DrawText(g,"Ridge "+new[]{"N–S","NE–SW","E–W","NW–SE"}[b.RidgeDirection]+" · h uses eave height when slope ≤10°",ModernUi.Body,new Rectangle(18,Height-40,Width-36,36),PowTheme.Muted,TextFormatFlags.WordBreak);
 }
 static void Dimension(Graphics g,PointF a,PointF b,string label,bool active,float dx,float dy){a=new PointF(a.X+dx,a.Y+dy);b=new PointF(b.X+dx,b.Y+dy);Color color=active?PowTheme.Teal:PowTheme.Muted;using(var pen=new Pen(color,active?2:1){StartCap=LineCap.DiamondAnchor,EndCap=LineCap.DiamondAnchor})g.DrawLine(pen,a,b);var midpoint=new Point((int)((a.X+b.X)/2)-65,(int)((a.Y+b.Y)/2)-20);TextRenderer.DrawText(g,label,ModernUi.Body,new Rectangle(midpoint,new Size(150,40)),color,ModernUi.Surface,TextFormatFlags.WordBreak);}
